L9: ];
L10: for (const mapping of mappings) {
L11:   const sourceText = "`Docs: " + "https:" + "//abitype.dev" + placeholder(mapping.name) + "`";
L12:   const replacementText =
L13:     '"Docs: " + "https://abitype.dev/{path}".replace("/{path}", () => ' + mapping.name + ")";
L14:   let replacements = 0;
L15:   for (const name of readdirSync("dist")) {
L16:     if (!name.endsWith(".js")) continue;
L17:     const path = join("dist", name);
L18:     const source = readFileSync(path, "utf8");
L19:     const occurrences = source.split(sourceText).length - 1;
L20:     if (occurrences === 0) continue;
L21:     replacements += occurrences;
L22:     writeFileSync(path, source.split(sourceText).join(replacementText));
L23:   }
L24:   if (replacements !== mapping.expected) {
L25:     throw new Error(
L26:       `expected ${mapping.expected} abitype ${mapping.name} URL templates, found ${replacements}`
L27:     );
L28:   }
L29: }
L30: const residualPrefix = "https:" + "//abitype.dev" + "$" + "{";
L31: for (const name of readdirSync("dist")) {
L32:   if (!name.endsWith(".js")) continue;
L33:   if (readFileSync(join("dist", name), "utf8").includes(residualPrefix)) {
L34:     throw new Error("unaccounted abitype URL template remains after normalization");
